\set VERBOSITY verbose
SELECT version();
CREATE SCHEMA evidence;
SET search_path=evidence,public;
CREATE TABLE p(id int PRIMARY KEY,u int UNIQUE);
CREATE TABLE c(id int PRIMARY KEY,pid int DEFAULT 2, n int CONSTRAINT pos CHECK(n>0), CONSTRAINT f FOREIGN KEY(pid) REFERENCES p(id) ON UPDATE CASCADE ON DELETE SET DEFAULT DEFERRABLE INITIALLY DEFERRED);
SELECT conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='c'::regclass ORDER BY conname;
INSERT INTO p VALUES(1,10),(2,20);
INSERT INTO c VALUES(1,1,NULL);
UPDATE c SET n=0 WHERE id=1;
INSERT INTO c VALUES(2,99,1);
BEGIN;
INSERT INTO c VALUES(2,99,1);
SAVEPOINT s;
SET CONSTRAINTS f IMMEDIATE;
ROLLBACK TO s;
DELETE FROM c WHERE id=2;
COMMIT;
SELECT * FROM c ORDER BY id;
BEGIN;
INSERT INTO c VALUES(2,99,1);
COMMIT;
SELECT * FROM c ORDER BY id;
CREATE TABLE self_ref(id int PRIMARY KEY,parent int REFERENCES self_ref(id) ON DELETE CASCADE);
INSERT INTO self_ref VALUES(1,1);
DELETE FROM self_ref WHERE id=1;
CREATE TABLE ck(n int CHECK(n IS NULL OR abs(n)>0),z int CHECK(z/0>0));
SELECT conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='ck'::regclass ORDER BY conname;
INSERT INTO ck(n) VALUES(NULL);
INSERT INTO ck(n) VALUES(0);
INSERT INTO ck(z) VALUES(1);
CREATE TABLE heap(a int,b int);
INSERT INTO heap VALUES(1,2),(2,3);
CREATE INDEX heap_b ON heap(b);
ALTER TABLE heap ADD PRIMARY KEY(a);
ALTER TABLE heap RENAME TO renamed;
SELECT conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='renamed'::regclass ORDER BY conname;
CREATE TABLE renamed(a int PRIMARY KEY);
CREATE TABLE h(a int);
CREATE TABLE h_pkey(x int);
ALTER TABLE h ADD PRIMARY KEY(a);
SELECT conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='h'::regclass ORDER BY conname;
CREATE TABLE bad(n int);
INSERT INTO bad VALUES(-1);
ALTER TABLE bad ADD CONSTRAINT positive CHECK(n>0) NOT VALID;
SELECT conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid='bad'::regclass ORDER BY conname;
ALTER TABLE bad VALIDATE CONSTRAINT positive;
ALTER TABLE bad DROP CONSTRAINT IF EXISTS absent;
CREATE TABLE restrict_child(id int REFERENCES p(id) ON UPDATE RESTRICT ON DELETE RESTRICT);
