DELETE FROM p WHERE id=1;
UPDATE p SET id=3 WHERE id=1;
CREATE TABLE na_child(id int REFERENCES p(id));
INSERT INTO na_child VALUES(2);
DELETE FROM p WHERE id=2;
DROP TABLE p;
DROP TABLE p CASCADE;
